AND SEIKYUU_MST.SKYSAKICD LIKE #{skysakicd,jdbcType=VARCHAR}||'%'
AND (SEIKYUU_MST.SKYSAKINMN1 LIKE '%'||#{skysakinmn1,jdbcType=VARCHAR}||'%' OR SEIKYUU_MST.SKYSAKINMN2 LIKE '%'||#{skysakinmn1,jdbcType=VARCHAR}||'%')
