SELECT SKSM3.APKIHONCD AS APKIHONCD ,SKSM3.SHOPCD AS SHOPCD ,SHPM.SHOPNM AS SHOPNM ,SKSM3.SKYSAKICD AS SKYSAKICD ,SKSM3.SHIMEDYDM1 AS SHIMEDYDM1 ,NVL(SKSM3.ZNKKURIKOSHIKIN1, 0) AS ZNKKURIKOSHIKIN1 ,NVL(SKSM3.KONKAIURIKIN1, 0) AS KONKAIURIKIN1 ,NVL(SKSM3.KONKAINYKNKIN1, 0) AS KONKAINYKNKIN1 ,NVL(SKSM3.KURIKOSHIKIN1, 0) AS KURIKOSHIKIN1 ,SKSM3.SHIMEDYDM2 AS SHIMEDYDM2 ,NVL(SKSM3.ZNKKURIKOSHIKIN2, 0) AS ZNKKURIKOSHIKIN2 ,NVL(SKSM3.KONKAIURIKIN2, 0) AS KONKAIURIKIN2 ,NVL(SKSM3.KONKAINYKNKIN2, 0) AS KONKAINYKNKIN2 ,NVL(SKSM3.KURIKOSHIKIN2, 0) AS KURIKOSHIKIN2 ,SKSM3.SHIMEDYDM3 AS SHIMEDYDM3 ,NVL(SKSM3.ZNKKURIKOSHIKIN3, 0) AS ZNKKURIKOSHIKIN3 ,NVL(SKSM3.KONKAIURIKIN3, 0) AS KONKAIURIKIN3 ,NVL(SKSM3.KONKAINYKNKIN3, 0) AS KONKAINYKNKIN3 ,NVL(SKSM3.KURIKOSHIKIN3, 0) AS KURIKOSHIKIN3 ,( SELECT SUM(TJST.GENZAIZD) FROM S02M013T TKSM INNER JOIN S02M050T TJST ON ( TJST.APKIHONCD = TKSM.APKIHONCD AND TJST.SHOPCD = TKSM.SHOPCD AND TJST.TOKUISAKICD = TKSM.TOKUISAKICD ) WHERE TKSM.APKIHONCD = SKSM3.APKIHONCD AND TKSM.SHOPCD = SKSM3.SHOPCD AND TKSM.SKYSAKICD = SKSM3.SKYSAKICD ) AS GENZAIZD ,NVL( ( SELECT SUM(NVL(NMST.NYKNKIN, 0) + NVL(NMST.NEBIKIKIN, 0) + NVL(NMST.TESURYO, 0)) FROM S10T001T NMST WHERE NMST.APKIHONCD = SKSM3.APKIHONCD AND NMST.SHOPCD = SKSM3.SHOPCD AND NMST.SKYSAKICD = SKSM3.SKYSAKICD AND NMST.SKYPRCSJISSIDD = '00000000' ), 0 ) AS NYUKIN ,SKSM4.TAIRYUKBN AS TAIRYUKBN ,CNDM1.ITEMNM AS TAIRYUKBNNM ,SKSM4.TAIRYUHASSEIKAISU AS TAIRYUHASSEIKAISU ,SKSM4.TAIRYUHASSEIKEIKADM AS TAIRYUHASSEIKEIKADM ,SKSM4.KAISHUHOHOKBN AS KAISHUHOHOKBN ,CNDM2.ITEMNM AS KAISHUHOHO ,SKSM4.SKYSAKINMN1 AS SKYSAKINMN1 ,SKSM4.SKYSAKINMN2 AS SKYSAKINMN2 ,SKSM4.SKYSHIMEDD AS SKYSHIMEDD ,SKSM4.SHRSAITO AS SHRSAITOKBN ,CNDM3.ITEMNM AS SHRSAITO ,SKSM4.SHRDD AS SHRDD ,SKSM4.SKYSAKIKANRIKBN AS SKYSAKIKANRIKBN ,CNDM4.ITEMNM AS SKYSAKIKANRIKBNNM ,SKSM4.YUBINNO AS YUBINNO ,SYKM1.MOJISETTEIATAI AS RENRAKUSAKINOKBNNM1 ,SYKM2.MOJISETTEIATAI AS RENRAKUSAKINOKBNNM2 ,SYKM3.MOJISETTEIATAI AS RENRAKUSAKINOKBNNM3 ,SYKM4.MOJISETTEIATAI AS RENRAKUSAKINOKBNNM4 ,SKSM4.RENRAKUSAKINON1 AS RENRAKUSAKINON1 ,SKSM4.RENRAKUSAKINON2 AS RENRAKUSAKINON2 ,SKSM4.RENRAKUSAKINON3 AS RENRAKUSAKINON3 ,SKSM4.RENRAKUSAKINON4 AS RENRAKUSAKINON4 ,SKSM4.ADRSN1 AS ADRSN1 ,SKSM4.ADRSN2 AS ADRSN2 ,SKSM4.ADRSN3 AS ADRSN3 ,SKSM4.TAIRYUKIN AS TAIRYUKIN ,SKSM4.SKYKBN AS SKYKBN ,SKSM4.JIGYOSHOCD AS JIGYOSHOCD ,JGSM.JIGYOSHONM AS JIGYOSHONM ,SKSM4.EIGYOTNSHACD AS EIGYOTNSHACD ,TTSM1.TNSHAMEI AS EIGYOTNSHAMEI ,SKSM4.KAISHUTNSHACD AS KAISHUTNSHACD ,TTSM2.TNSHAMEI AS KAISHUTNSHAMEI FROM ( SELECT SKSM2.APKIHONCD ,SKSM2.SHOPCD ,SKSM2.SKYSAKICD ,MAX(DECODE(RANK_1, 1, SKSM2.SHIMEDYDM, NULL)) AS SHIMEDYDM1 ,SUM(DECODE(RANK_1, 1, ZNKKURIKOSHIKIN, 0)) AS ZNKKURIKOSHIKIN1 ,SUM(DECODE(RANK_1, 1, KONKAIURIKIN, 0)) AS KONKAIURIKIN1 ,SUM(DECODE(RANK_1, 1, KONKAINYKNKIN, 0)) AS KONKAINYKNKIN1 ,SUM(DECODE(RANK_1, 1, KURIKOSHIKIN, 0)) AS KURIKOSHIKIN1 ,MAX(DECODE(RANK_1, 2, SKSM2.SHIMEDYDM, NULL)) AS SHIMEDYDM2 ,SUM(DECODE(RANK_1, 2, ZNKKURIKOSHIKIN, 0)) AS ZNKKURIKOSHIKIN2 ,SUM(DECODE(RANK_1, 2, KONKAIURIKIN, 0)) AS KONKAIURIKIN2 ,SUM(DECODE(RANK_1, 2, KONKAINYKNKIN, 0)) AS KONKAINYKNKIN2 ,SUM(DECODE(RANK_1, 2, KURIKOSHIKIN, 0)) AS KURIKOSHIKIN2 ,MAX(DECODE(RANK_1, 3, SKSM2.SHIMEDYDM, NULL)) AS SHIMEDYDM3 ,SUM(DECODE(RANK_1, 3, ZNKKURIKOSHIKIN, 0)) AS ZNKKURIKOSHIKIN3 ,SUM(DECODE(RANK_1, 3, KONKAIURIKIN, 0)) AS KONKAIURIKIN3 ,SUM(DECODE(RANK_1, 3, KONKAINYKNKIN, 0)) AS KONKAINYKNKIN3 ,SUM(DECODE(RANK_1, 3, KURIKOSHIKIN, 0)) AS KURIKOSHIKIN3 FROM ( SELECT SKSM.APKIHONCD ,SKSM.SHOPCD ,SKSM.SKYSAKICD ,DENSE_RANK() OVER ( PARTITION BY SKSM.SKYSAKICD ORDER BY TO_NUMBER(SZDT.SHIMEDYDM || lpad(SHIMEDD, 2, '0')) DESC ) RANK_1 ,SZDT.SHIMEDYDM ,SUM(NVL(SZDT.ZNKKURIKOSHIKIN, 0)) ZNKKURIKOSHIKIN ,(SUM(NVL(SZDT.KONKAITAXNUKIURIKIN, 0)) + SUM(NVL(SZDT.KONKAISHOHITAXKIN, 0))) KONKAIURIKIN ,SUM(NVL(SZDT.KONKAINYKNKIN, 0)) KONKAINYKNKIN ,SUM(NVL(SZDT.KURIKOSHIKIN, 0)) KURIKOSHIKIN FROM S02M017T SKSM LEFT JOIN S07T001T SZDT ON ( SZDT.APKIHONCD = SKSM.APKIHONCD AND SZDT.SHOPCD = SKSM.SHOPCD AND SZDT.SKYSAKICD = SKSM.SKYSAKICD AND SZDT.SKYPRCSJISSIKBN = '1' AND SZDT.YUKOKBN = '1' ) WHERE SKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND SKSM.YUKOKBN = '1'
AND SKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
AND SKSM.EIGYOTNSHACD = #{eigyotnshacd,jdbcType=VARCHAR}
AND SKSM.KAISHUTNSHACD = #{kaishutnshacd,jdbcType=VARCHAR}
AND SKSM.TAIRYUKBN IN
