AND ( SKSM.TAIRYUHASSEIKEIKADM >= 2 OR (SKSM.TAIRYUHASSEIKAISU >= '2' AND (SKSM.TAIRYUHASSEIKEIKADM = 1 OR SKSM.TAIRYUHASSEIKEIKADM = 0 OR SKSM.TAIRYUHASSEIKEIKADM IS NULL ) ) )
AND ( ( (SKSM.TAIRYUHASSEIKAISU = 1 OR SKSM.TAIRYUHASSEIKAISU = 0 OR SKSM.TAIRYUHASSEIKAISU IS NULL) AND (SKSM.TAIRYUHASSEIKEIKADM = 1 OR SKSM.TAIRYUHASSEIKEIKADM = 0 OR SKSM.TAIRYUHASSEIKEIKADM IS NULL) ) )
AND ( SKSM.TAIRYUHASSEIKAISU >= '2' AND (SKSM.TAIRYUHASSEIKEIKADM = 1 OR SKSM.TAIRYUHASSEIKEIKADM = 0 OR SKSM.TAIRYUHASSEIKEIKADM IS NULL) )
AND ( ( (SKSM.TAIRYUHASSEIKAISU = 1 OR SKSM.TAIRYUHASSEIKAISU = 0 OR SKSM.TAIRYUHASSEIKAISU IS NULL) AND (SKSM.TAIRYUHASSEIKEIKADM = 1 OR SKSM.TAIRYUHASSEIKEIKADM = 0 OR SKSM.TAIRYUHASSEIKEIKADM IS NULL) ) OR (SKSM.TAIRYUHASSEIKAISU >= '2' AND (SKSM.TAIRYUHASSEIKEIKADM = 1 OR SKSM.TAIRYUHASSEIKEIKADM = 0 OR SKSM.TAIRYUHASSEIKEIKADM IS NULL) ) )
AND SKSM.KAISHUHOHOKBN IN
