AND TO_NUMBER(NVL(SKSM.TAIRYUHASSEIKEIKADM,0)) >= TO_NUMBER(NVL(#{dm,jdbcType=VARCHAR},0))
GROUP BY SKSM.APKIHONCD ,SKSM.SHOPCD ,SKSM.SKYSAKICD ,SZDT.SHIMEDYDM ,SZDT.SHIMEDD ) SKSM2 WHERE SKSM2.RANK_1 <= 3 GROUP BY SKSM2.APKIHONCD ,SKSM2.SHOPCD ,SKSM2.SKYSAKICD ) SKSM3 INNER JOIN S02M017T SKSM4 ON ( SKSM4.APKIHONCD = SKSM3.APKIHONCD AND SKSM4.SHOPCD = SKSM3.SHOPCD AND SKSM4.SKYSAKICD = SKSM3.SKYSAKICD ) INNER JOIN S02M046T SHPM ON ( SKSM4.APKIHONCD = SHPM.APKIHONCD AND SKSM4.SHOPCD = SHPM.SHOPCD ) LEFT JOIN S02M047T JGSM ON ( JGSM.APKIHONCD = SKSM4.APKIHONCD AND JGSM.SHOPCD = SKSM4.SHOPCD AND JGSM.JIGYOSHOCD = SKSM4.JIGYOSHOCD ) LEFT JOIN S02M003T TTSM1 ON ( TTSM1.APKIHONCD = SKSM4.APKIHONCD AND TTSM1.SHOPCD = SKSM4.SHOPCD AND TTSM1.TNSHACD = SKSM4.EIGYOTNSHACD ) LEFT JOIN S02M003T TTSM2 ON ( TTSM2.APKIHONCD = SKSM4.APKIHONCD AND TTSM2.SHOPCD = SKSM4.SHOPCD AND TTSM2.TNSHACD = SKSM4.KAISHUTNSHACD ) LEFT OUTER JOIN S01M004T CNDM1 ON ( CNDM1.CONDITIONID = 'CN085' AND CNDM1.SETTEIATAI = SKSM4.TAIRYUKBN ) LEFT OUTER JOIN S01M004T CNDM2 ON ( CNDM2.CONDITIONID = 'CN160' AND CNDM2.SETTEIATAI = SKSM4.KAISHUHOHOKBN ) LEFT OUTER JOIN S01M004T CNDM3 ON ( CNDM3.CONDITIONID = 'CN086' AND CNDM3.SETTEIATAI = SKSM4.SHRSAITO ) LEFT OUTER JOIN S01M004T CNDM4 ON ( CNDM4.CONDITIONID = 'CN159' AND CNDM4.SETTEIATAI = SKSM4.SKYSAKIKANRIKBN ) LEFT OUTER JOIN S02M006T SYKM1 ON ( SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO = '011' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = SKSM4.RENRAKUSAKINOKBNN1 ) LEFT OUTER JOIN S02M006T SYKM2 ON ( SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '011' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEICD = SKSM4.RENRAKUSAKINOKBNN2 ) LEFT OUTER JOIN S02M006T SYKM3 ON ( SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.SETTEINO = '011' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEICD = SKSM4.RENRAKUSAKINOKBNN3 ) LEFT OUTER JOIN S02M006T SYKM4 ON ( SYKM4.APKIHONCD = '000' AND SYKM4.SHOPCD = '000' AND SYKM4.SETTEINO = '011' AND SYKM4.RCRDKBN = 'M' AND SYKM4.SETTEICD = SKSM4.RENRAKUSAKINOKBNN4 ) ORDER BY SKSM4.JIGYOSHOCD ,SKSM4.KAISHUTNSHACD ,SKSM4.YUBINNO ,SKSM4.SKYSAKICD

SELECT NVL(M_SEIKYU.JIGYOSHOCD, ' ') AS JGYCD ,M_SEIKYU.SKYSAKICD ,M_SEIKYU.SKYSAKINMN1 ,SUM(NVL(ZANDAKARIREKI.URIKIN, 0)) + SUM(NVL(ZANDAKARIREKI.SHOHITAX, 0 )) AS URIAGE
,SUM(NVL( ZANDAKARIREKI.ZANDAKA_KESIKOMI , 0 )) AS KESIKOMI
,SUM(NVL( ZANDAKARIREKI.RIREKI_KESIKOMI, 0 )) AS KESIKOMI
,SUM(NVL( ZANDAKARIREKI.MINYUKIN, 0 )) AS MINYU ,M_SEIKYU.TAIRYUKBN ,NVL( M_SEIKYU.TAIRYUKIN , 0 ) AS TAIRYUKIN ,CDT.ITEMNM TAIRYUKBNNM FROM S02M017T M_SEIKYU INNER JOIN ( SELECT SEIKYUZANDAKA.APKIHONCD ,SEIKYUZANDAKA.SHOPCD ,SEIKYUZANDAKA.SKYSAKICD ,NVL(SEIKYUZANDAKA.KONKAITAXNUKIURIKIN, 0) AS URIKIN ,NVL(SEIKYUZANDAKA.KONKAISHOHITAXKIN, 0) AS SHOHITAX ,SEIKYUZANDAKA.KESHIKOMIKIN AS ZANDAKA_KESIKOMI
,SUM(NYUKINRIREKI.KESHIKOMIKIN) AS RIREKI_KESIKOMI
,SEIKYUZANDAKA.KESHIKOMIZD AS MINYUKIN FROM S07T001T SEIKYUZANDAKA
INNER JOIN S10T004T NYUKINRIREKI ON NYUKINRIREKI.APKIHONCD = SEIKYUZANDAKA.APKIHONCD AND NYUKINRIREKI.SHOPCD = SEIKYUZANDAKA.SHOPCD AND NYUKINRIREKI.SKYSAKICD = SEIKYUZANDAKA.SKYSAKICD AND NYUKINRIREKI.TOKUISAKICD = SEIKYUZANDAKA.TOKUISAKICD AND NYUKINRIREKI.SHOKAISKYSHONO = SEIKYUZANDAKA.SKYSHONO AND NYUKINRIREKI.SKYPRCSJISSIKBN = SEIKYUZANDAKA.SKYPRCSJISSIKBN AND NYUKINRIREKI.YUKOKBN = '1'
