AND NYUKINRIREKI.NYKNDD <= #{entity.nyknddshry,jdbcType=VARCHAR}
AND NYUKINRIREKI.KSHKMNYKNKIND IN
#{item}
WHERE SEIKYUZANDAKA.APKIHONCD = #{entity.apkihoncd,jdbcType=VARCHAR} AND SEIKYUZANDAKA.SHOPCD = #{entity.shopcd,jdbcType=VARCHAR}
AND SEIKYUZANDAKA.SKYSAKICD LIKE #{entity.skysakicd,jdbcType=VARCHAR} || '%'
SEIKYUZANDAKA.KAISHUHOHOKBN = #{item.kaishuHohoKbn}
