AND SEIKYUZANDAKA.SHRYTIDYDMDD <= #{entity.nyknytiddshry,jdbcType=VARCHAR}
AND SEIKYUZANDAKA.KESHIKOMIZD <> 0
AND SEIKYUZANDAKA.YUKOKBN = '1' GROUP BY SEIKYUZANDAKA.APKIHONCD ,SEIKYUZANDAKA.SHOPCD ,SEIKYUZANDAKA.SKYSAKICD ,SEIKYUZANDAKA.KONKAITAXNUKIURIKIN ,SEIKYUZANDAKA.KONKAISHOHITAXKIN ,SEIKYUZANDAKA.KESHIKOMIKIN ,SEIKYUZANDAKA.KESHIKOMIZD ,SEIKYUZANDAKA.TOKUISAKICD ,SEIKYUZANDAKA.SHIMEDYDM ,SEIKYUZANDAKA.SHIMEDD ,SEIKYUZANDAKA.SKYPRCSJISSIKBN ) ZANDAKARIREKI ON M_SEIKYU.APKIHONCD = ZANDAKARIREKI.APKIHONCD AND M_SEIKYU.SHOPCD = ZANDAKARIREKI.SHOPCD AND M_SEIKYU.SKYSAKICD = ZANDAKARIREKI.SKYSAKICD LEFT JOIN S01M004T CDT ON CDT.CONDITIONID = 'CN085' AND CDT.ITEMNO = M_SEIKYU.TAIRYUKBN WHERE M_SEIKYU.APKIHONCD = #{entity.apkihoncd,jdbcType=VARCHAR} AND M_SEIKYU.SHOPCD = #{entity.shopcd,jdbcType=VARCHAR}
AND M_SEIKYU.SKYSAKICD LIKE #{entity.skysakicd,jdbcType=VARCHAR} || '%'
AND M_SEIKYU.JIGYOSHOCD = #{entity.jigyoshosentaku,jdbcType=VARCHAR}
