SELECT * FROM( SELECT SKSM.APKIHONCD APKIHONCD ,SKSM.SHOPCD SHOPCD ,SKSM.SKYSAKICD SKYSAKICD ,SKSM.SKYSAKINMN1 SKYSAKINMN1 ,SKSM.JIGYOSHOCD JIGYOSHOCD ,SKSM.KAISHUHOHOKBN KAISHUHOHOKBN ,CNDM1.ITEMNM KAISHUHOHOKBNNM ,SKSM.TAIRYUKBN TAIRYUKBN ,CNDM2.ITEMNM TAIRYUKBNNM ,MAX(TO_CHAR(TO_DATE( (SZDT.SHIMEDYDM || SZDT.SHIMEDD),'yyyymmdd'),'YYYYMMDD')) MAXDATE ,CASE WHEN MAX(SZDT.TOKUSOKUJOPRNTDD) = '00000000' THEN '未処理' ELSE '処理済' END STATUS FROM ( S02M017T SKSM
INNER JOIN S09T001T KRKT ON(KRKT.APKIHONCD = SKSM.APKIHONCD AND KRKT.SHOPCD = SKSM.SHOPCD AND KRKT.SKYSAKICD = SKSM.SKYSAKICD AND KRKT.SHIMEDYDM = #{shimedydm,jdbcType=VARCHAR} AND KRKT.JOTAI = '4' AND KRKT.KSIKEKKA <> '0' )
) INNER JOIN S07T001T SZDT ON(SZDT.APKIHONCD = SKSM.APKIHONCD AND SZDT.SHOPCD = SKSM.SHOPCD AND SZDT.SKYSAKICD = SKSM.SKYSAKICD AND SZDT.YUKOKBN = '1' ) LEFT JOIN S01M004T CNDM1 ON(CNDM1.CONDITIONID = 'CN160' AND CNDM1.SETTEIATAI = SKSM.KAISHUHOHOKBN) LEFT JOIN S01M004T CNDM2 ON(CNDM2.CONDITIONID = 'CN085' AND CNDM2.SETTEIATAI = SKSM.TAIRYUKBN) WHERE SKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SKSM.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND SKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
AND SKSM.TAIRYUKBN IN
#{item}
GROUP BY SKSM.APKIHONCD ,SKSM.SHOPCD ,SKSM.SKYSAKICD ,SKSM.SKYSAKINMN1 ,SKSM.JIGYOSHOCD ,SKSM.KAISHUHOHOKBN ,SKSM.TAIRYUKBN ,CNDM1.ITEMNM ,CNDM2.ITEMNM ) WHERE ROWNUM <= #{rownum} + 1
